# Try: fill the boundary-connected regions with 0, keep enclosed as 8
from collections import deque

def fill_boundary():
    rows, cols = len(grid), len(grid[0])
    # First, mark all 8s touching the boundary
    visits = [[False]*cols for _ in range(rows)]
    queue = deque()

    # Add all boundary cells that are 8
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1) and grid[r][c] == 8:
                visits[r][c] = True
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visits[nr][nc] and grid[nr][nc] == 8:
                visits[nr][nc] = True
                queue.append((nr, nc))

    # Create output: boundary-connected become 0, enclosed keep 8
    output = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and visits[r][c]:
                output[r][c] = 0
    return output

